// Business Charts v7: single `context` arg.
const data = context.panel.data;
const theme = context.grafana.theme;

const frame = data.series && data.series[0];
if (!frame) { return {}; }
const arr = (f) => (f && f.values && f.values.toArray) ? f.values.toArray() : (f ? f.values : []);
const tf = frame.fields.find((f) => f.type === 'time');
const vf = frame.fields.find((f) => f.type === 'number');
const ts = arr(tf), vs = arr(vf);

const key = (d) => d.getFullYear() + '-' +
  String(d.getMonth() + 1).padStart(2, '0') + '-' +
  String(d.getDate()).padStart(2, '0');

// one value per LOCAL calendar day (points land on UTC-aligned steps)
const byDay = new Map();
for (let i = 0; i < ts.length; i++) {
  const v = vs[i];
  if (v === null || v === undefined || Number.isNaN(v)) { continue; }
  byDay.set(key(new Date(ts[i])), v);
}

// sum days into Monday-start calendar weeks
const byWeek = new Map();
const daysIn = new Map();
byDay.forEach((v, k) => {
  const p = k.split('-').map(Number);
  const d = new Date(p[0], p[1] - 1, p[2]);
  d.setDate(d.getDate() - ((d.getDay() + 6) % 7));   // Mon=0 .. Sun=6 -> back to Monday
  const w = key(d);
  byWeek.set(w, (byWeek.get(w) || 0) + v);
  daysIn.set(w, (daysIn.get(w) || 0) + 1);
});

// which bucket is the in-progress week?
const today = new Date();
today.setDate(today.getDate() - ((today.getDay() + 6) % 7));
const currentWeek = key(today);

// A week clipped by the range edge is not a low week -- it's a partial one.
// Drop those, but keep the current week, which is legitimately in progress.
const weeks = Array.from(byWeek.keys()).sort()
  .filter((w) => daysIn.get(w) === 7 || w === currentWeek);
if (!weeks.length) { return {}; }
const totals = weeks.map((w) => Math.round(byWeek.get(w)));
const complete = weeks.map((w, i) => [i, totals[i]]).filter((p) => weeks[p[0]] !== currentWeek);

const fit = (pts) => {
  const n = pts.length;
  if (n < 2) { return null; }
  let sx = 0, sy = 0, sxx = 0, sxy = 0;
  for (let i = 0; i < n; i++) { const x = pts[i][0], y = pts[i][1]; sx += x; sy += y; sxx += x * x; sxy += x * y; }
  const den = n * sxx - sx * sx;
  if (!den) { return null; }
  const b = (n * sxy - sx * sy) / den;
  const a = (sy - b * sx) / n;
  return (x) => a + b * x;
};
const f = fit(complete);
const trend = f ? weeks.map((w, i) => Math.round(f(i))) : [];

const MON = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
const labels = weeks.map((w) => { const p = w.split('-').map(Number); return MON[p[1] - 1] + ' ' + p[2]; });

const c = (theme && theme.colors) ? theme.colors : null;
const ink2 = c ? c.text.secondary : '#888';
const grid = c ? c.border.weak : '#2a2d33';

return {
  animationDuration: 250,
  animationDurationUpdate: 250,
  animationEasing: 'cubicOut',
  animationEasingUpdate: 'cubicOut',
  grid: { left: 60, right: 20, top: 20, bottom: 55 },
  tooltip: { trigger: 'axis', valueFormatter: (v) => Math.round(v).toLocaleString() },
  legend: { bottom: 0, textStyle: { color: ink2 }, data: ['weekly steps', 'trend'] },
  xAxis: {
    type: 'category', data: labels, boundaryGap: false,
    axisLabel: { color: ink2 }, axisLine: { lineStyle: { color: grid } }
  },
  yAxis: {
    type: 'value', scale: true,
    axisLabel: { color: ink2, formatter: (v) => (v / 1000) + 'K' },
    splitLine: { lineStyle: { color: grid } }
  },
  series: [
    {
      name: 'weekly steps', type: 'line', data: totals,
      symbolSize: 7, smooth: 0.2,
      lineStyle: { width: 2, color: '#3D71D9' }, itemStyle: { color: '#3D71D9' },
      areaStyle: { color: { type: 'linear', x: 0, y: 0, x2: 0, y2: 1, colorStops: [
        { offset: 0, color: 'rgba(87,148,242,0.55)' },
        { offset: 0.6, color: 'rgba(87,148,242,0.15)' },
        { offset: 1, color: 'rgba(87,148,242,0.00)' }
      ] } },
      markLine: {
        silent: true, symbol: 'none',
        data: [{ yAxis: 70000, label: { formatter: '70K goal', color: ink2, position: 'insideEndTop' },
                 lineStyle: { color: ink2, type: 'solid', width: 1 } }]
      }
    },
    {
      name: 'trend', type: 'line', data: trend, symbol: 'none',
      lineStyle: { width: 2, type: 'dashed', color: '#C4162A' }, itemStyle: { color: '#C4162A' }
    }
  ]
};

// Business Charts v7 passes a single `context` argument:
//   { grafana: {theme, ...}, panel: {data, chart}, echarts, ecStat }
const data = context.panel.data;
const theme = context.grafana.theme;

const frame = data.series && data.series[0];
if (!frame) { return {}; }

const arr = (f) => (f && f.values && f.values.toArray) ? f.values.toArray() : (f ? f.values : []);
const tf = frame.fields.find((f) => f.type === 'time');
const vf = frame.fields.find((f) => f.type === 'number');
const ts = arr(tf), vs = arr(vf);

// Bucket by LOCAL calendar day; last value wins within a day.
const byDay = new Map();
for (let i = 0; i < ts.length; i++) {
  const v = vs[i];
  if (v === null || v === undefined || Number.isNaN(v)) { continue; }
  const d = new Date(ts[i]);
  const key = d.getFullYear() + '-' +
    String(d.getMonth() + 1).padStart(2, '0') + '-' +
    String(d.getDate()).padStart(2, '0');
  byDay.set(key, v);
}
const points = Array.from(byDay, (e) => [e[0], e[1]]);
if (!points.length) { return {}; }

const days = points.map((p) => p[0]).sort();
const range = [days[0], days[days.length - 1]];

const c = (theme && theme.colors) ? theme.colors : null;
const ink   = c ? c.text.primary   : '#ccc';
const ink2  = c ? c.text.secondary : '#888';
const empty = c ? c.background.secondary : '#22252b';
const gap   = c ? c.background.primary   : '#111217';

return {
  animationDuration: 250,
  animationDurationUpdate: 250,
  animationEasing: 'cubicOut',
  animationEasingUpdate: 'cubicOut',
  tooltip: {
    formatter: (p) => p.value[0] + '<br/><b>' + Math.round(p.value[1]).toLocaleString() + '</b> steps'
  },
  visualMap: {
    type: 'piecewise',
    orient: 'horizontal',
    left: 'center',
    bottom: 0,
    itemWidth: 12,
    itemHeight: 12,
    textStyle: { color: ink2 },
    pieces: [
      { lt: 5000,               color: '#C4162A', label: '< 5K' },
      { gte: 5000,  lt: 10000,  color: '#FF9830', label: '5-10K' },
      { gte: 10000, lt: 15000,  color: '#56A64B', label: '10-15K' },
      { gte: 15000,             color: '#19730E', label: '15K+' }
    ]
  },
  calendar: {
    top: 30,
    left: 45,
    right: 20,
    cellSize: ['auto', 15],
    range: range,
    itemStyle: { color: empty, borderColor: gap, borderWidth: 2 },
    splitLine: { show: false },
    yearLabel: { show: false },
    dayLabel: { firstDay: 1, color: ink2, nameMap: ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'] },
    monthLabel: { color: ink }
  },
  series: [{
    type: 'heatmap',
    coordinateSystem: 'calendar',
    data: points,
    itemStyle: { borderRadius: 2, borderColor: gap, borderWidth: 2 }
  }]
};
